import { useEffect, useRef, useState } from 'react';

import { authApi } from '@mealawe/api';
import { useAuthStore } from '@mealawe/state';

/** First 3 letters of the username (spaces stripped) + a random 7-digit
 * number — mirrors MealaweUserApp's `generateReferrelCode()` exactly, so
 * codes generated by either app resolve the same way server-side. */
function generateCode(userName: string | undefined): string {
  const seed = (userName || 'MEALAWE').replace(/\s+/g, '').slice(0, 3).toUpperCase();
  return `${seed}${Math.ceil(Math.random() * 10000000)}`;
}

/**
 * The current user's referral code, lazily generated + persisted on first
 * use if the profile doesn't already have one (mirrors the Ionic app's
 * on-view-enter `generateReferrelCode()` — generation happens here instead
 * of server-side, so both apps must keep the same algorithm).
 */
export function useReferralCode(): { code: string | undefined; generating: boolean } {
  const profile = useAuthStore((s) => s.profile);
  const setProfile = useAuthStore((s) => s.setProfile);
  const [generating, setGenerating] = useState(false);
  const startedRef = useRef(false);

  const code = profile?.['referralCode'] as string | undefined;

  useEffect(() => {
    if (code || !profile?._id || startedRef.current) return;
    startedRef.current = true;
    const generated = generateCode(profile.userName);
    setGenerating(true);
    authApi
      .setReferralCode(profile._id, { referralCode: generated })
      .then((updated) => setProfile(updated?._id ? updated : { ...profile, referralCode: generated }))
      .catch(() => {})
      .finally(() => setGenerating(false));
  }, [code, profile, setProfile]);

  return { code, generating };
}
